package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.context.*;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.*;
import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.*;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import static org.assertj.core.api.Assertions.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Cross-domain app-role PG bank reconciliation; no live bank or production originals. */
class FinanceBankControlIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate jdbc;static NamedParameterJdbcTemplate named;static TransactionTemplate tx;static FinanceBankControlService service;
 static final UUID T=UUID.fromString("10000000-0000-0000-0000-000000000001");static final LocalDate DAY=LocalDate.of(2026,10,24);UUID hotel,company,book,bank,actor,author,reviewer,cashier;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var ds=pg.getPostgresDatabase();jdbc=new JdbcTemplate(ds);jdbc.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("100").load().migrate();named=new NamedParameterJdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));service=new FinanceBankControlService(named,new TenantDatabaseContext(jdbc,true),new AccessPolicy(),null);}
 @AfterAll static void stop()throws Exception{if(pg!=null)pg.close();}@AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed(){hotel=UUID.randomUUID();company=UUID.randomUUID();book=UUID.randomUUID();bank=UUID.randomUUID();actor=account();author=account();reviewer=account();cashier=account();jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'银行实际来源验收','HOTEL')",hotel,T,hotel.toString());jdbc.update("insert into finance_company(id,tenant_id,name,tax_number) values(?,?,'银行验收法人',?)",company,T,company.toString().replace("-",""));jdbc.update("insert into fa_book(id,tenant_id,hotel_id,company_id,name,start_month) values(?,?,?,?,'银行验收账套','2026-10-01')",book,T,hotel,company);jdbc.update("insert into fo_bank_account(id,tenant_id,hotel_id,company_id,name,account_number,bank_name,opening_date,opening_balance,created_by) values(?,?,?,?,'银行测试账户','000012345678901234','隔离银行','2026-10-01',1000,?)",bank,T,hotel,company,actor);as("finance.read","finance.pay");}
 @Test void originalCashAndDatedFxCorrectionsNeverRewriteHistoricalBalanceOrCountPreOpeningRows(){UUID doc=document("PAYABLE"),cash=action(doc,"PAYMENT","100.00","2026-10-04"),bankTx=bankTx("OUT","100.00","2026-10-04","真实供应商");UUID match=UUID.randomUUID();jdbc.update("insert into fo_bank_match(id,tenant_id,transaction_id,action_id,amount,request_id,note,actor_id,created_at) values(?,?,?,?,100,?,'原匹配',?,'2026-10-05 10:00:00+08')",match,T,bankTx,cash,UUID.randomUUID(),actor);fx("OPERATION",cash,doc,"100.00","40.00","2026-10-04",match,"40.00");bankTx("IN","9999.00","2026-09-30","期初前已包含，不再累计");var old=call(()->service.statement(bank,LocalDate.of(2026,10,10)));assertThat(old).containsEntry("complete",true).containsEntry("statementBalance","900.00").containsEntry("controlledCashBalance","900.00");assertThat(rows(old.get("cashJournal"))).noneMatch(r->"FX_CASH_CORRECTION".equals(r.get("sourceKind")));var current=call(()->service.statement(bank,DAY));assertThat(current).containsEntry("complete",false).containsEntry("controlledCashBalance","940.00").containsEntry("difference","-40.00");assertThat(rows(current.get("cashJournal"))).anySatisfy(r->assertThat(r).containsEntry("sourceKind","FX_CASH_CORRECTION").containsEntry("amount","-40.00").containsEntry("occurredOn","2026-10-20"));assertThat(json(current.get("bankAccount"))).contains("****1234").doesNotContain("000012345678901234");assertThat(rows(current.get("transactions"))).hasSize(1);}
 @Test void businessCashUsesOnlyExplicitBankAssignmentsAndReversalDates(){UUID batch=UUID.randomUUID(),entry=UUID.randomUUID(),movement=UUID.randomUUID();jdbc.update("insert into fb_revenue_batch(id,tenant_id,hotel_id,company_id,source,channel,business_date,night_audit_date,revision,expected_count,control_total,source_reference,status,source_hash,created_by,reviewer_id) values(?,?,?,?,'PMS','DIRECT','2026-10-08','2026-10-09',1,1,200,'真实收款来源','CONFIRMED',?,?,?)",batch,T,hotel,company,"a".repeat(64),author,reviewer);jdbc.update("insert into fb_revenue_entry(id,tenant_id,batch_id,hotel_id,company_id,external_id,kind,customer,channel,due_date,amount,net_amount,tax_amount,commission,fee,active) values(?,?,?,?,?,'PMS-001','AR','隔离客户','DIRECT','2026-10-08',200,200,0,0,0,true)",entry,T,batch,hotel,company);jdbc.update("insert into fb_revenue_movement(id,tenant_id,entry_id,kind,amount,occurred_on,bank_reference,note,created_by) values(?,?,?,'RECEIPT',200,'2026-10-08','隔离真实收款','不按门店推断银行',?)",movement,T,entry,actor);UUID transaction=bankTx("IN","200.00","2026-10-08","隔离客户");var unresolved=call(()->service.statement(bank,DAY));assertThat(unresolved).containsEntry("complete",false).containsEntry("controlledCashBalance",null);assertThat(rows(unresolved.get("cashJournal"))).isEmpty();UUID match=UUID.randomUUID();jdbc.update("insert into fb_bank_match(id,tenant_id,transaction_id,source_type,source_id,amount,request_id,note,actor_id,created_at) values(?,?,?,'REVENUE',?,200,?,'明确归属真实流水',?,'2026-10-09 10:00:00+08')",match,T,transaction,movement,UUID.randomUUID(),actor);UUID correction=UUID.randomUUID(),event=event(movement,"FB_REVENUE_AR","200.00");jdbc.update("insert into fb_cash_correction(id,tenant_id,source_type,source_id,hotel_id,company_id,original_kind,original_source_event_id,amount,business_date,accounting_on,note,proof,created_by) values(?,?,'REVENUE',?,?,?,'RECEIPT',?,50,'2026-10-08','2026-10-20','已核实原登记差错','{}',?)",correction,T,movement,hotel,company,event,actor);jdbc.update("insert into fb_bank_match_reversal(id,tenant_id,match_id,correction_id,amount,accounting_on,created_by) values(?,?,?,?,50,'2026-10-20',?)",UUID.randomUUID(),T,match,correction,actor);var old=call(()->service.statement(bank,LocalDate.of(2026,10,10)));assertThat(old).containsEntry("complete",true).containsEntry("controlledCashBalance","1200.00");var current=call(()->service.statement(bank,DAY));assertThat(current).containsEntry("controlledCashBalance","1150.00").containsEntry("difference","50.00").containsEntry("complete",false);assertThat(rows(current.get("cashJournal"))).anySatisfy(r->assertThat(r).containsEntry("sourceKind","FB_MATCH_REVERSAL").containsEntry("amount","-50.00"));}
 @Test void claimMatchingUsesActualNetPaymentAndNetCrossDomainRemainingAllocation(){UUID[] first=claimPayment("100.00"),second=claimPayment("40.00");UUID transaction=bankTx("OUT","100.00","2026-10-24","真实员工报销");UUID match=UUID.randomUUID();jdbc.update("insert into fc_claim_bank_match(id,tenant_id,transaction_id,instruction_id,amount,note,created_by,created_at) values(?,?,?,?,80,'原付款分配',?,'2026-10-24 01:00:00+08')",match,T,transaction,first[1],actor);fx("CLAIM",first[2],first[0],"100.00","40.00","2026-10-24",match,"20.00");assertThatThrownBy(()->call(()->service.matchClaim(transaction,new FinanceControlModels.ClaimMatch(UUID.randomUUID(),first[1],new BigDecimal("1.00"),"不能超过净付款")))).hasMessageContaining("差错冲回");UUID request=UUID.randomUUID();call(()->service.matchClaim(transaction,new FinanceControlModels.ClaimMatch(request,second[1],new BigDecimal("40.00"),"净释放的银行余额分配给另一真实付款")));assertThat(call(()->service.matchClaim(transaction,new FinanceControlModels.ClaimMatch(request,second[1],new BigDecimal("40.00"),"净释放的银行余额分配给另一真实付款")))).containsEntry("id",request);assertThatThrownBy(()->call(()->service.matchClaim(transaction,new FinanceControlModels.ClaimMatch(UUID.randomUUID(),second[1],BigDecimal.ONE,"不能重复分配")))).hasMessageContaining("净剩余余额");}
 @Test void salaryAndUnknownEntityNeverAppearAsCompleteAndScopeCannotLeakAccount(){UUID salary=document("PAYROLL"),cash=action(salary,"PAYMENT","30.00","2026-10-10"),transaction=bankTx("OUT","30.00","2026-10-10","敏感工资员工姓名");jdbc.update("insert into fo_bank_match(tenant_id,transaction_id,action_id,amount,request_id,note,actor_id,created_at) values(?,?,?,30,?,'工资实际匹配',?,'2026-10-11 10:00:00+08')",T,transaction,cash,UUID.randomUUID(),actor);var restricted=call(()->service.statement(bank,DAY));assertThat(restricted).containsEntry("complete",false).containsEntry("controlledCashBalance",null);assertThat(json(restricted)).doesNotContain("敏感工资员工姓名");assertThat(rows(restricted.get("cashJournal"))).isEmpty();as("finance.read","finance.payroll");assertThat(call(()->service.statement(bank,DAY))).containsEntry("complete",true).containsEntry("controlledCashBalance","970.00");jdbc.update("update fo_bank_account set company_id=null where id=?",bank);assertThat(call(()->service.statement(bank,DAY))).containsEntry("entityKnown",false).containsEntry("complete",false).containsEntry("controlledCashBalance",null);TenantContext.set(new TenantPrincipal(T,actor,"TEST",Set.of("TEST"),Set.of("finance.read"),Set.of(UUID.randomUUID()),Set.of(),false,UUID.randomUUID()));assertThatThrownBy(()->call(()->service.statement(bank,DAY))).isInstanceOf(AccessDeniedException.class);}
 @Test void supplierRefundUsesActualLinkedBankAndAccountingDateWithoutInventingAnotherCashMovement(){UUID order=UUID.randomUUID(),line=UUID.randomUUID(),receipt=UUID.randomUUID(),recognition=UUID.randomUUID(),returned=UUID.randomUUID();jdbc.update("insert into procurement_order(id,tenant_id,hotel_id,source,status,applicant_id,title,supplier) values(?,?,?,'REQUEST','COMPLETED',?,'退款原采购','真实供应商')",order,T,hotel,author);jdbc.update("insert into procurement_line(id,tenant_id,hotel_id,order_id,line_kind,item_name,sku,base_unit,input_unit,factor,input_quantity,quantity,unit_price,approved_quantity) values(?,?,?,?,'SERVICE','已验收检修','SERVICE','项','项',1,1,1,50,1)",line,T,hotel,order);jdbc.update("insert into procurement_receipt(id,tenant_id,order_id,receiver_id,status,reviewer_id,reviewed_at) values(?,?,?,?,'APPROVED',?,now())",receipt,T,order,author,reviewer);jdbc.update("insert into fs_recognition(id,tenant_id,hotel_id,company_id,receipt_id,applicant_id,confirmer_id,cashier_id,status,estimated_amount,invoice_amount,invoice_ids,lines,differences,note,accounting_date) values(?,?,?,?,?,?,?,?,'CONFIRMED',50,50,'[]','[]','[]','真实暂估转确认','2026-10-10')",recognition,T,hotel,company,receipt,author,reviewer,cashier);jdbc.update("insert into fs_return(id,tenant_id,recognition_id,hotel_id,line_id,quantity,kind,applicant_id,reviewer_id,status,supplier_credit,note,accounting_date) values(?,?,?,?,?,1,'RETURN',?,?,'APPROVED',50,'真实已核实退款','2026-10-18')",returned,T,recognition,hotel,line,author,reviewer);UUID transaction=bankTx("IN","50.00","2026-10-18","真实供应商退款");jdbc.update("insert into fs_settlement(id,tenant_id,return_id,kind,amount,bank_transaction_id,actor_id,note,business_date,accounting_date) values(?,?,?,'REFUND',50,?,?,'实际退款已关联银行','2026-10-18','2026-10-20')",UUID.randomUUID(),T,returned,transaction,actor);assertThat(call(()->service.statement(bank,LocalDate.of(2026,10,19)))).containsEntry("complete",false).containsEntry("controlledCashBalance","1000.00");var after=call(()->service.statement(bank,DAY));assertThat(after).containsEntry("complete",true).containsEntry("controlledCashBalance","1050.00");assertThat(rows(after.get("cashJournal"))).anySatisfy(r->assertThat(r).containsEntry("sourceKind","FS_REFUND").containsEntry("amount","50.00"));}
 private UUID document(String type){UUID id=UUID.randomUUID();jdbc.update("insert into fo_document(id,tenant_id,hotel_id,company_id,applicant_id,type,title,business_date,amount,details,lines,status) values(?,?,?,?,?,?,'隔离业务真实现金来源','2026-10-01',1000,'{}','[]','APPROVED')",id,T,hotel,company,author,type);return id;}
 private UUID action(UUID document,String kind,String amount,String day){UUID id=UUID.randomUUID();jdbc.update("insert into fo_action(id,tenant_id,document_id,actor_id,action,amount,occurred_on,reference,bank_account_id,request_id) values(?,?,?,?,?,cast(? as numeric),cast(? as date),'实际资金依据',?,?)",id,T,document,actor,kind,amount,day,bank,UUID.randomUUID());return id;}
 private UUID bankTx(String direction,String amount,String day,String name){UUID id=UUID.randomUUID();jdbc.update("insert into fo_bank_transaction(id,tenant_id,bank_account_id,batch_id,external_id,occurred_on,direction,amount,counterparty,reference,source_hash,created_by) values(?,?,?,?,?,cast(? as date),?,cast(? as numeric),?,'真实银行摘要',?,?)",id,T,bank,UUID.randomUUID(),id.toString(),day,direction,amount,name,"b".repeat(64),actor);return id;}
 private UUID event(UUID source,String type,String amount){UUID id=UUID.randomUUID();jdbc.update("insert into fa_source_event(id,tenant_id,hotel_id,book_id,company_id,source_type,source_id,event_key,business_date,accounting_date,amount,summary,metadata,request_hash,status) values(?,?,?,?,?,?,?,'PAYMENT','2026-10-01','2026-10-01',cast(? as numeric),'真实现金来源','{}',?,'PENDING_MAPPING')",id,T,hotel,book,company,type,source,amount,id.toString());return id;}
 private void fx(String kind,UUID source,UUID document,String original,String amount,String day,UUID match,String reversed){UUID id=UUID.randomUUID(),event=event(source,"FX_TEST",original);String accounting=kind.equals("CLAIM")?"2026-10-24":"2026-10-20";jdbc.update("insert into fx_cash_correction(id,tenant_id,source_kind,source_id,document_id,hotel_id,company_id,original_source_event_id,original_date,accounting_on,original_amount,amount,source_version,source_hash,request_hash,reason,matching_reversals,snapshot,created_by,reviewer_id,reviewed_by,status,version) values(?,?,?,?,?,?,?,?,cast(? as date),cast(? as date),cast(? as numeric),cast(? as numeric),0,?,?,'独立确认原登记差错','[]','{}',?,?,?,'CONFIRMED',1)",id,T,kind,source,document,hotel,company,event,day,accounting,original,amount,"c".repeat(64),"d".repeat(64),author,reviewer,reviewer);jdbc.update("insert into fx_bank_match_reversal(tenant_id,source_kind,match_id,correction_id,amount,accounting_on,created_by) values(?,?,?,?,cast(? as numeric),cast(? as date),?)",T,kind,match,id,reversed,accounting,reviewer);}
 private UUID[] claimPayment(String amount){UUID employee=UUID.randomUUID(),assignment=UUID.randomUUID(),claim=UUID.randomUUID(),instruction=UUID.randomUUID(),payment=UUID.randomUUID();jdbc.update("insert into employee(id,tenant_id,account_id,employee_no,name) values(?,?,?,?, '真实报销测试员工')",employee,T,author,employee.toString());jdbc.update("insert into employee_position_assignment(id,tenant_id,employee_id,org_unit_id,position_id,valid_from) select ?,?,?,?,id,'2026-10-01'::date from position_definition where tenant_id=? limit 1",assignment,T,employee,hotel,T);jdbc.update("insert into finance_claim(id,tenant_id,applicant_id,assignment_id,hotel_id,company_id,applicant_name,hotel_name,company_name,company_tax_number,business_date,requested_amount,approved_amount,status,manager_account_id,finance_account_id,leader_account_id) values(?,?,?,?,?,?,'报销测试员工','本店','测试主体','TEST','2026-10-24',cast(? as numeric),cast(? as numeric),'APPROVED',?,?,?)",claim,T,author,assignment,hotel,company,amount,amount,actor,reviewer,cashier);jdbc.update("insert into fc_cash_instruction(id,tenant_id,hotel_id,company_id,source_kind,source_id,source_version,action,amount,occurred_on,bank_account_id,beneficiary_snapshot,bank_snapshot,reference,note,snapshot_hash,status,created_by,reviewer_id,cashier_id,applicant_id) values(?,?,?,?,'CLAIM',?,0,'PAYMENT',cast(? as numeric),'2026-10-24',?,'{}','{}','实际付款指令','已独立复核',?,'EXECUTED',?,?,?,?)",instruction,T,hotel,company,claim,amount,bank,"e".repeat(64),actor,reviewer,cashier,author);jdbc.update("insert into finance_payment(id,tenant_id,claim_id,amount,reference,paid_on,actor_id,request_id) values(?,?,?,cast(? as numeric),'真实已付款','2026-10-24',?,?)",payment,T,claim,amount,cashier,instruction);return new UUID[]{claim,instruction,payment};}
 private UUID account(){UUID id=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'银行验收账号')",id,T,id.toString());return id;}
 private void as(String...permissions){TenantContext.set(new TenantPrincipal(T,actor,"TEST",Set.of("TEST"),Set.of(permissions),Set.of(hotel),Set.of(),false,UUID.randomUUID()));}
 private static <R>R call(Supplier<R> body){return tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");return body.get();});}
}
